#include<bits/stdc++.h>

using namespace std;
using ll=long long;

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  string s;
  cin >> s;
  ll l=s.size();
  ll res=0;
  for(ll i=0;i<l;i++){
    if(s[i]=='C'){
      res+=min(i+1,l-i);
    }
  }
  cout << res << "\n";
  return 0;
}
